mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T3.FINPROD_MARKET_ID finprodMarketId, T3.FINPROD_ID finprodId, T7.FINPROD_MARKET_ID shareId, T7.FINPROD_ID shareFinprodId, T3.FINPROD_NAME finprodName, T7.FINPROD_NAME shareName, T2.PORTFOLIO_NAME portfolioName, T1.ENTRUST_NUM*100 entrustAmt, T1.ENTRUST_NUM*100 stocketrPriceTotal, T4.SHARE_PRICE sharePrice, T5.CON_PRICE conPrice, T4.PREB preb, T4.PREC prec, T1.INV_AIM invAim, T1.TRADE_MARKET tradeMarket, T1.CCY ccy, T1.VDATE vdate, T1.MDATE mdate, T1.INV_MANAGER_ID invManagerId, T1.REMARK remark FROM ETR_ENTRUST T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID INNER JOIN ETR_ENTRUST_ADD T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID INNER JOIN FIN_PRODUCT_CONVERTIBLE T5 ON T3.FINPROD_ID = T5.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID INNER JOIN FIN_PRODUCT T7 ON T5.CON_FINPROD_ID = T7.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T8 ON T8.FINPROD_ID = T3.FINPROD_ID
AND T6.USER_ID = #{userId} AND (T8.TYPE_6 = #{type6_B14} OR T8.TYPE_6 = #{type6_B15})
AND ((T2.PORTFOLIO_ID IN
null) or T2.PORTFOLIO_ID in (
#{prot}
) or (T2.PARENT_PORTFOLIO_ID IN
null) or T2.PARENT_PORTFOLIO_ID in (
#{prot}
) )
AND (T3.FINPROD_ID like concat('%',concat(#{finprodId},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND (T7.FINPROD_MARKET_ID like concat('%',concat(#{shareId},'%')) OR T7.FINPROD_ABBR like concat('%',concat(#{shareId},'%')))
AND T1.ENTRUST_STATUS = #{entrustStatus}
AND T1.VDATE >=STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.TRADE_MARKET_MODE=#{tradeMarketMode}
AND T1.PS=#{ps}
order by T1.ENTRUST_ID DESC

SELECT T1.PORTFOLIO_ID portfolioId, T5.FINPROD_MARKET_ID finprodMarketId, T5.FINPROD_ID finprodId, T7.FINPROD_MARKET_ID shareId, T7.FINPROD_ID shareFinprodId, T5.FINPROD_NAME finprodName, T7.FINPROD_NAME shareName, T2.PORTFOLIO_NAME portfolioName, T1.SEC_ACCT_ID secAcctId, IFNULL(T1.AMOUNT*100,0) holdetrPriceTotal, IFNULL(T1.AMOUNT*100,0) conetrPriceTotal, ROUND((T8.CLOSE_PRICE-1)/1,2) prec, ROUND((T8.CLOSE_PRICE-(100/T3.CON_PRICE*T9.CLOSE_PRICE))/(100/T3.CON_PRICE*T9.CLOSE_PRICE),2) preb, T8.CLOSE_PRICE bondPrice, 1 pbondvalue, T3.CON_PRICE conPrice, T3.RESALE_PRICE resalePrice, T3.REDEEM_PRICE redeemPrice, T9.CLOSE_PRICE sharePrice, 100/T3.CON_PRICE conProportion, 100/T3.CON_PRICE*T9.CLOSE_PRICE conValue, T1.INV_AIM invAim, T5.VDATE finvdate, T5.MDATE finmdate, T3.CON_VDATE conVdate, T5.CCY ccy, T5.TRADE_MARKET tradeMarket, T3.CON_SHARE_ID conShareId FROM (SELECT * FROM ETR_SEC_POSITION psp where HODING_TYPE = #{HODING_TYPE_E01} AND CDATE = STR_TO_DATE(#{sysDate},'%Y-%m-%d') and not exists ( select 1 from ETR_SEC_POSITION tpsp where tpsp.CDATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d') and tpsp.HODING_TYPE = psp.HODING_TYPE and tpsp.PORTFOLIO_ID = psp.PORTFOLIO_ID and tpsp.FINPROD_ID = psp.FINPROD_ID and tpsp.BRANCH = psp.BRANCH and tpsp.INV_AIM = psp.INV_AIM and tpsp.CCY = psp.CCY and tpsp.SEC_ACCT_ID = psp.SEC_ACCT_ID and tpsp.CDATE > psp.CDATE )) T1 LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_CONVERTIBLE T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT T5 ON T3.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T2.PORTFOLIO_ID = T6.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T3.CON_FINPROD_ID LEFT JOIN (SELECT * FROM ( select @rownum:=@rownum+1 rownum, MBMI.*, if(@SEC_ID=MBMI.SEC_ID,@rank:=@rank+1,@rank:=1) as px, @SEC_ID:=MBMI.SEC_ID from(SELECT * from MST_BOND_MARKET_INFO WHERE VALUE_DATE < = STR_TO_DATE(#{sysDate},'%Y-%m-%d') order by SEC_ID,VALUE_DATE DESC)MBMI, (select @rownum:=0,@SEC_ID:=null,@rank:=0)b
) MB WHERE MB.px = 1 ) T8 ON T5.FINPROD_MARKET_ID = T8.SEC_ID LEFT JOIN (SELECT * FROM ( select @rownum:=@rownum+1 rownum, MSP.*, if(@SHARES_ID=MSP.SHARES_ID,@rank:=@rank+1,@rank:=1) as px, @SHARES_ID:=MSP.SHARES_ID from(SELECT * from MST_SHARE_PRICE WHERE DEAL_DATE < = STR_TO_DATE(#{sysDate},'%Y-%m-%d') order by SHARES_ID,DEAL_DATE DESC)MSP, (select @rownum:=0,@SHARES_ID:=null,@rank:=0)b
) MS WHERE MS.px = 1 ) T9 ON T7.FINPROD_MARKET_ID = T9.SHARES_ID LEFT JOIN FIN_PRODUCT_TYPE T10 ON T10.FINPROD_ID = T5.FINPROD_ID
AND T6.USER_ID = #{userId} AND (T10.TYPE_6 = #{type6_B14} OR T10.TYPE_6 = #{type6_B15}) AND T2.INVEST_YESORNO = 'Y'
AND ((T2.PORTFOLIO_ID IN
null) or T2.PORTFOLIO_ID in (
#{prot}
) or (T2.PARENT_PORTFOLIO_ID IN
null) or T2.PARENT_PORTFOLIO_ID in (
#{prot}
) )
AND (T5.FINPROD_ID like concat('%',concat(#{finprodId},'%')) OR T5.FINPROD_NAME like concat('%',concat(#{finprodId},'%')))
AND (T7.FINPROD_MARKET_ID like concat('%',concat(#{shareId},'%')) OR T7.FINPROD_NAME like concat('%',concat(#{shareId},'%')))
AND IFNULL(T1.AMOUNT*100,0) > 0 AND T5.MDATE >STR_TO_DATE(#{sysDate},'%Y-%m-%d') AND STR_TO_DATE(#{sysDate},'%Y-%m-%d') > T3.CON_VDATE
AND T9.CLOSE_PRICE >= T3.REDEEM_PRICE
AND T3.RESALE_PRICE >= T9.CLOSE_PRICE
order by T1.PORTFOLIO_ID DESC

select T1.FINPROD_ID id, IFNULL(T3.FINPROD_ABBR,T3.FINPROD_NAME) text, T4.FINPROD_MARKET_ID, T4.FINPROD_NAME, T3.TRADE_MARKET, T4.FINPROD_ID shareFinprodId, T3.CCY, T1.CON_SHARE_ID, T1.CON_VDATE, T1.CON_PRICE, ROUND((T5.CLOSE_PRICE-1)/1,2) prec, ROUND((T5.CLOSE_PRICE-(100/T1.CON_PRICE*T6.CLOSE_PRICE))/(100/T1.CON_PRICE*T6.CLOSE_PRICE),2) preb, ROUND(100/T1.CON_PRICE*T6.CLOSE_PRICE,14) conValue, 1 pbondvalue, T5.CLOSE_PRICE bondPrice, T6.CLOSE_PRICE sharePrice from FIN_PRODUCT_CONVERTIBLE T1 LEFT JOIN FIN_PRODUCT_TYPE T2 ON T1.FINPROD_ID = T2.FINPROD_ID LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_PRODUCT T4 ON T1.CON_FINPROD_ID = T4.FINPROD_ID LEFT JOIN (SELECT * FROM ( select @rownum:=@rownum+1 rownum, MBMI.*, if(@SEC_ID=MBMI.SEC_ID,@rank:=@rank+1,@rank:=1) as px, @SEC_ID:=MBMI.SEC_ID from(SELECT * from MST_BOND_MARKET_INFO WHERE VALUE_DATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d') order by SEC_ID,VALUE_DATE DESC)MBMI, (select @rownum:=0,@SEC_ID:=null,@rank:=0)b
) MB WHERE MB.px = 1 ) T5 ON T3.FINPROD_MARKET_ID = T5.SEC_ID LEFT JOIN (SELECT * FROM ( select @rownum:=@rownum+1 rownum, MSP.*, if(@SHARES_ID=MSP.SHARES_ID,@rank:=@rank+1,@rank:=1) as px, @SHARES_ID:=MSP.SHARES_ID from(SELECT * from MST_SHARE_PRICE WHERE DEAL_DATE <= STR_TO_DATE(#{sysDate},'%Y-%m-%d') order by SHARES_ID,DEAL_DATE DESC)MSP, (select @rownum:=0,@SHARES_ID:=null,@rank:=0)b
) MS WHERE MS.px = 1 ) T6 ON T4.FINPROD_MARKET_ID = T6.SHARES_ID
T1.FINPROD_ID =#{initValue,jdbcType=VARCHAR}
AND (T1.FINPROD_ID like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) OR T3.FINPROD_NAME like concat('%',concat(#{search,jdbcType=VARCHAR},'%')) )
AND T2.TYPE_6 = #{Bond_Type1} OR T2.TYPE_6 = #{Bond_Type2}

SELECT
sum(IFNULL(psp.amount,0))*100 amount
FROM
ETR_SEC_POSITION psp
where HODING_TYPE = #{hodingType}
and psp.PORTFOLIO_ID = #{portfolioId}
and psp.FINPROD_ID = #{finprodId}
and psp.CDATE <= STR_TO_DATE(#{cdate},'%Y-%m-%d')

    and psp.BRANCH = #{branch}


    and psp.INV_AIM = #{invAim}


    and psp.ccy = #{ccy}


    and psp.SEC_ACCT_ID = #{secAcctId}


    and psp.SEC_ACCT_ID = #{chlId}

and not exists (
    select
    1
    from
    ETR_SEC_POSITION tpsp
    where
    tpsp.CDATE <= STR_TO_DATE(#{cdate},'%Y-%m-%d')
    and tpsp.HODING_TYPE = psp.HODING_TYPE
    and tpsp.PORTFOLIO_ID = psp.PORTFOLIO_ID
    and tpsp.FINPROD_ID = psp.FINPROD_ID
    and tpsp.BRANCH = psp.BRANCH
    and tpsp.INV_AIM = psp.INV_AIM
    and tpsp.CCY = psp.CCY
    and tpsp.SEC_ACCT_ID = psp.SEC_ACCT_ID
    and tpsp.CDATE > psp.CDATE
)

select T7.PORTFOLIO_ID,T7.SEC_ACCT_ID,SUM(T7.AMT) PRIN_AMT from( select T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID,SUM((CASE WHEN T1.PS =#{pin} THEN T2.AMT WHEN #{pout} THEN T2.AMT*-1 END)*IFNULL(T6.SCALE,0)) AMT from TRD_STASEC_FLOW T1 INNER JOIN TRD_STASEC_FLOW_DETAIL T2 ON T1.SEQNO = T2.SEQNO left join (select T3.FINPROD_ID,T3.SCALE from FIN_STDSEC_CONVERSE_RADIO T3 INNER JOIN (select T4.FINPROD_ID,MAX(T4.VDATE) VDATE from FIN_STDSEC_CONVERSE_RADIO T4
T4.VDATE <= #{sysDate}
group by T4.FINPROD_ID) T5 ON T3.FINPROD_ID = T5.FINPROD_ID
T3.VDATE = T5.VDATE
) T6 ON T6.FINPROD_ID = T2.FINPROD_ID
T1.PORTFOLIO_ID = #{portfolioId} AND T1.SEC_ACCT_ID = #{manageId}
group by T1.PORTFOLIO_ID,T1.SEC_ACCT_ID,T2.FINPROD_ID ) T7 group by T7.PORTFOLIO_ID,T7.SEC_ACCT_ID
